import test from 'node:test';
import assert from 'node:assert/strict';
import { AIR_CONTROL, DT, RUN_ACCEL } from '../../src/physics.js';
import { createState, step } from '../../src/physics.js';

const level = {
  spawn: [0, 10, 0],
  killY: -12,
  platforms: [],
  coins: [],
  goal: { id: 'goal', min: [0, 0, 0], max: [0, 0, 0] }
};

let state = createState(level);
state.vel = [0, 0, 0];
state.grounded = false;

const accelGround = 60 * (1/60); // RUN_ACCEL * DT
const accelAir = accelGround * 0.1; // * AIR_CONTROL

state = step(state, { x: 1, z: 0, jump: false }, level, 0);
assert.strictEqual(state.vel[0], accelAir);

state = step(state, { x: 1, z: 0, jump: false }, level, 1);
assert.strictEqual(state.vel[0], accelAir * 2); // no friction in air

import test from 'node:test';
import assert from 'node:assert/strict';
import { TERMINAL_SPEED } from '../../src/physics.js';
import { createState, step } from '../../src/physics.js';

const level = {
  spawn: [0, 100, 0],
  killY: -12,
  platforms: [],
  coins: [],
  goal: { id: 'goal', min: [0, 0, 0], max: [0, 0, 0] }
};

let state = createState(level);
state.vel = [0, -50, 0]; // already fast falling

// Apply gravity several times to ensure clamping
for (let i = 0; i < 10; i++) {
  state = step(state, { x: 0, z: 0, jump: false }, level, i);
}

assert.strictEqual(state.vel[1], -18); // -TERMINAL_SPEED

import test from 'node:test';
import assert from 'node:assert/strict';
import { JUMP_SPEED } from '../../src/physics.js';
import { createState, step } from '../../src/physics.js';

const level = {
  spawn: [0, 0, 0],
  killY: -12,
  platforms: [{ id: 'ground', min: [-10, -1, -10], max: [10, 0, 10] }],
  coins: [],
  goal: { id: 'goal', min: [0, 0, 0], max: [0, 0, 0] }
};

// Case 1: jumping from rest
let state = createState(level);
state = step(state, { x: 0, z: 0, jump: true }, level, 0);
assert.strictEqual(state.vel[1], 14);

// Case 2: jumping while falling fast
state = createState(level);
state.vel = [0, -100, 0];
state = step(state, { x: 0, z: 0, jump: true }, level, 0);
assert.strictEqual(state.vel[1], 14); // overridden, not -100 + 14

// Case 3: jumping while moving upward
state = createState(level);
state.vel = [0, 20, 0];
state = step(state, { x: 0, z: 0, jump: true }, level, 0);
assert.strictEqual(state.vel[1], 14); // set to JUMP_SPEED, not added
